use crate::{io::Bound,lifecycle::*};use anyhow::{Context,Result,ensure};use serde_json::{Value,json};use std::path::Path;
pub fn runtime(policy:&Value,policy_bound:&Bound,admission:&Bound,capsule:&Bound)->Result<Value>{ensure!(policy["schema"]=="epoch163-first-output128-input-policy-v1"&&policy["node"]==json!(node_program())&&policy["guard"]==json!(guard_program())&&policy.get("admission").is_none()&&policy.get("input_policy").is_none(),"original node policy projection");let mut v=policy.clone();v["schema"]=json!("epoch163-first-output128-private-plan-v1");v["input_policy"]=json!(policy_bound);v["admission"]=json!(admission);v["admission_capsule"]=json!(capsule);Ok(v)}
pub fn observer(before:&Value,iid:&str)->Result<Value>{ensure!(crate::io::hex(iid,32)&&before["schema"]=="jetstreamer-horizon-live-resource-sample-config-v2"&&before["minimum_interval_seconds"]==1800&&before["observation_reason"]=="routine","exact routine observer");let mut next=before.clone();let rows=next["diagnostic_replays"].as_array_mut().context("observer diagnostics")?;ensure!(!rows.iter().any(|r|r["range"]=="163"||r["producer_unit"]==PARENT),"observer duplicate claim");rows.push(json!({"controller_unit":PARENT,"producer_unit":PARENT,"expected_controller_invocation_id":iid,"expected_producer_invocation_id":iid,"range":"163","scratch_path":format!("{WORK}/scratch"),"worker_executable_basename":"historical-worker"}));Ok(next)}
pub fn fleet_plan(prior:&Value,previous:&Bound,enrollment:&Bound,iid:&str,output:&Path)->Result<Value>{ensure!(crate::io::hex(iid,32)&&prior["first_epoch"]==101&&prior["last_epoch"]==200,"same assigned century");let mut next=prior.clone();next["output"]=json!(output);next["previous_fleet"]=json!(previous);next["metadata_event"]=json!(enrollment);let rows=next["diagnostics"].as_array_mut().context("fleet diagnostics")?;ensure!(!rows.iter().any(|r|r["unit"]==PARENT),"fleet already contains first128");rows.push(json!({"epoch":163,"unit":PARENT,"invocation_id":iid,"scratch_path":format!("{WORK}/scratch"),"launch_receipt":enrollment}));let units=next["tracked_units"].as_array_mut().context("fleet tracked native sources")?;let suffix=["horizon-extract145-prefix-shared72h-20261107-v8g1.service","horizon-guard145-prefix-shared72h-20261107-v8g1.service","horizon-guard145-prefix-shared72h-20261107-v8g1.timer"];ensure!(units.len()>=3&&units[units.len()-3..].iter().zip(suffix).all(|(v,s)|v==s),"exact retained145 typedFrame suffix");let index=units.len()-3;for(unit,offset)in [PARENT,GUARD,STOP,TIMER,ADMIT,ENROLL,RELEASE].iter().zip(0..){ensure!(!units.iter().any(|v|v==*unit),"duplicate native first128 role");units.insert(index+offset,json!(unit));}Ok(next)}
#[cfg(test)]mod tests{use super::*;
 fn b(s:&str)->Bound{Bound{path:format!("/normal/{s}.json").into(),sha256:"a".repeat(64)}}
 #[test]fn runtime_only_extends_actual_policy_without_new_current_fields(){let p=json!({"schema":"epoch163-first-output128-input-policy-v1","node":node_program(),"guard":guard_program(),"admission_program":{"path":"/normal/helper22","sha256":"b".repeat(64)},"memory":{"original":1}});let out=runtime(&p,&b("p"),&b("a"),&b("c")).unwrap();let mut projection=out.clone();let o=projection.as_object_mut().unwrap();for k in ["admission","input_policy","admission_capsule"]{o.remove(k);}projection["schema"]=p["schema"].clone();assert_eq!(projection,p);assert!(out.get("held_transition").is_none());}
 #[test]fn observer_preserves_every_unrelated_field_and_rejects_duplicate(){let before=json!({"schema":"jetstreamer-horizon-live-resource-sample-config-v2","minimum_interval_seconds":1800,"observation_reason":"routine","diagnostic_replays":[],"previous_sample":"original","not_before_utc":"unchanged"});let after=observer(&before,&"b".repeat(32)).unwrap();assert_eq!(after["previous_sample"],before["previous_sample"]);assert_eq!(after["not_before_utc"],before["not_before_utc"]);assert!(observer(&after,&"b".repeat(32)).is_err());assert!(observer(&before,"bad").is_err());}
 #[test]fn same_sample_fleet_addition_preserves_terminal145_suffix_and_all_other_sources(){let suffix=json!(["old.service","horizon-extract145-prefix-shared72h-20261107-v8g1.service","horizon-guard145-prefix-shared72h-20261107-v8g1.service","horizon-guard145-prefix-shared72h-20261107-v8g1.timer"]);let before=json!({"schema":"fixed","first_epoch":101,"last_epoch":200,"diagnostics":[],"tracked_units":suffix,"observer":{"original":1},"pipeline_claims":[1,2],"gates":{"163":{"state":"blocked-qualification","evidence":[1]}}});let after=fleet_plan(&before,&b("before"),&b("enrollment"),&"c".repeat(32),Path::new("/var/lib/new.json")).unwrap();assert_eq!(after["observer"],before["observer"]);assert_eq!(after["pipeline_claims"],before["pipeline_claims"]);assert_eq!(after["gates"],before["gates"]);let units=after["tracked_units"].as_array().unwrap();assert_eq!(&units[units.len()-3..],&before["tracked_units"].as_array().unwrap()[1..]);assert!(fleet_plan(&after,&b("before"),&b("enrollment"),&"c".repeat(32),Path::new("/var/lib/new.json")).is_err());}
 #[test]fn actor_source_has_only_finite2g_host_network_and_original_readonly_credentials(){let a=vec!["/usr/local/lib/jetstreamer/helper/jetstreamer-r2".into(),"admit-first163128".into(),"/normal/spec.json".into()];let source=actor_source(&a,&[WORK.into()]).unwrap();assert!(source.contains("MemoryMax=2G\n")&&source.contains("PrivateNetwork=no\n")&&source.contains("Restart=no\n")&&source.contains("RemainAfterExit=no\n")&&source.contains("EnvironmentFile=/etc/jetstreamer/horizon-r2.env\n"));let mut bad=a;bad.push("injected\nExecStart=/bad".into());assert!(actor_source(&bad,&[]).is_err());}
 #[test]fn helper_routes_cannot_invoke_generic_or_native_restore(){assert!(helper_argv(&b("helper"),"fleet-reconcile",&b("spec")).is_err());for route in ["admit-first163128","enroll-first163128","release-first163128"]{assert!(helper_argv(&b("helper"),route,&b("spec")).is_ok());}}
}
